   "id": "zc579f291",
   "sez": "mondo",
   "titolo": "Pakistan, il governo impone lo stato di emergenza nella provincia roccaforte di Imran Khan",
   "orig": "Pakistan imposes emergency rule in former prime minister's stronghold",
   "lead": "Le autorità centrali del Pakistan hanno proclamato lo stato di emergenza nella provincia amministrata dal partito politico dell'ex primo ministro Imran Khan, attualmente detenuto in carcere. Il provvedimento straordinario è stato introdotto per assumere il controllo della sicurezza nell'area ritenuta la principale roccaforte politica dell'ex leader, dove le tensioni con il governo federale sono cresciute costantemente nelle ultime settimane dopo la carcerazione dell'ex capo dell'esecutivo. Lo riferisce NPR.",
   "more": [
    "Lo stato di emergenza in Pakistan conferisce poteri speciali all'esecutivo federale e alle forze di sicurezza per limitare le libertà di assemblea e gestire direttamente l'ordine pubblico nelle province in caso di crisi istituzionale."
   ],
