   "id": "z8b29ac66",
   "sez": "sport",
   "titolo": "La Formula 1 torna in Africa: accordo decennale con il Ruanda a partire dai primi anni Trenta",
   "orig": "F1 returns to Africa for first time since 1993 with 10-year Rwanda deal from ‘early 2030s’",
   "lead": "I vertici della Formula 1 hanno annunciato che il Ruanda ospiterà il Gran Premio d'Africa a partire dai primi anni del decennio 2030, in base a un accordo decennale storico. La gara si disputerà su un nuovo circuito permanente a Bugesera, situato a venticinque miglia a sud della capitale Kigali e nelle vicinanze del nuovo scalo aeroportuale internazionale. L'annuncio accoglie l'appello sostenuto per anni dal pluricampione del mondo Lewis Hamilton per riportare il massimo campionato automobilistico nel continente africano, dove l'ultima gara si era svolta nel 1993.",
   "more": [
    "Il Gran Premio del Sudafrica del 1993 a Kyalami era stata l'ultima apparizione della Formula 1 nel continente africano; il progetto ruandese si inserisce nei piani di Liberty Media per espandere il calendario verso nuovi mercati globali con impianti all'avanguardia."
   ],
