     "n": "Il Fatto Quotidiano",
     "p": "IT",
     "c": "Roma",
     "u": "https://www.ilfattoquotidiano.it/2026/10/13/ha-mangiato-qualcosa-di-cosi-voluminoso-da-aver-teso-la-pelle-fino-a-renderla-quasi-trasparente-mar-dei-caraibi-pesce-inghiottitore-nero-mangia-prede-fino-a-dieci-volte-piu-grandi-di-lui/8536583/",
     "angolo": "",
