   "sez": "economia",
   "titolo": "Uzbekistan e Georgia puntano a un interscambio commerciale da un miliardo di dollari",
   "orig": "Uzbekistan and Georgia target $1 billion in bilateral trade.",
   "lead": "Uzbekistan e Georgia hanno fissato l'obiettivo ambizioso di elevare il valore del loro interscambio commerciale bilaterale a un miliardo di dollari. Durante un recente incontro intergovernativo, le delegazioni dei due Paesi hanno discusso misure per espandere i legami commerciali, sviluppare nuove rotte di trasporto trans-caspiche e lanciare progetti congiunti in settori chiave come industria, agricoltura, energia e turismo. Tra le proposte concrete figura anche la creazione di un centro logistico uzbeko presso il porto georgiano di Poti per facilitare il transito delle merci verso i mercati internazionali.",
   "more": [
    "L'interscambio tra Paesi dell'Asia centrale e del Caucaso sta assumendo una rilevanza strategica crescente come alternativa alle rotte commerciali tradizionali. La collaborazione economica tra Uzbekistan e Georgia sfrutta la posizione geografica di quest'ultima come sbocco marittimo fondamentale, mentre l'Uzbekistan cerca di diversificare le proprie esportazioni industriali e agricole attraverso infrastrutture di trasporto più efficienti."
   ],
