   "sez": "sport",
   "titolo": "Hong Kong, sconti al mercato dei fiori per i tifosi di calcio locale",
   "orig": "Football fans get Flower Market discounts",
   "lead": "I tifosi di calcio di Hong Kong potranno usufruire di sconti esclusivi presso quaranta attività commerciali del Flower Market di Mong Kok dopo aver assistito alle partite nel vicino Mong Kok Stadium. L'iniziativa fa parte di una campagna volta a stimolare l'economia locale attraverso il riutilizzo dei biglietti delle partite. I fan dovranno presentare il tagliando presso i negozi aderenti, tra cui fiorai, ristoranti e una clinica di medicina tradizionale cinese. La promozione copre cinque incontri della Premier League di Hong Kong programmati fino al 19 dicembre. Lo riferisce RTHK.",
   "more": [
    "Le strategie di marketing territoriale che collegano eventi sportivi e attività commerciali locali sono comuni per incentivare i consumi nelle aree urbane. Coinvolgere mercati storici e piccole imprese permette di creare un indotto economico che va oltre lo stadio, fidelizzando i tifosi e supportando il tessuto economico del quartiere attraverso sconti dedicati."
   ],
