   "titolo": "Kenya, test negativo per il sospetto caso di Ebola all'ospedale di Nanyuki",
   "orig": "Nanyuki hospital issues statement after suspected Ebola case tests negative",
   "lead": "L'ospedale di Nanyuki, in Kenya, ha rilasciato una dichiarazione ufficiale confermando che un sospetto caso di Ebola testato presso la struttura ha dato esito negativo. I risultati dei test di laboratorio, condotti dal National Virology Reference Laboratory, sono stati resi noti martedì 13 ottobre 2026, smentendo i timori di una possibile diffusione del virus. La notizia ha riportato la calma nella regione, confermando l'efficacia dei protocolli di sorveglianza sanitaria attivati per monitorare tempestivamente eventuali emergenze legate a febbri emorragiche. Lo riferisce Citizen Digital.",
   "more": [
    "L'Ebola è una febbre emorragica virale altamente contagiosa e letale. Nei Paesi dell'Africa orientale, la sorveglianza sanitaria è estremamente rigorosa; ogni caso sospetto viene isolato immediatamente e sottoposto a test molecolari presso laboratori di riferimento nazionali per prevenire epidemie su larga scala e garantire una risposta rapida delle autorità competenti."
   ],
