   "id": "zaa73f805",
   "sez": "ambiente",
   "titolo": "Elefanti marini guidano la scoperta di nuove correnti nell'Oceano Australe",
   "orig": "Découverte de nouveaux courants marins grâce aux éléphants de mer des Kerguelen",
   "lead": "Una vasta colonia di circa 350.000 elefanti marini che abita le isole Kerguelen ha permesso ai ricercatori di scoprire nuove correnti marine. Grazie alla collaborazione di questi animali, dotati di sensori speciali, gli scienziati hanno potuto raccogliere dati oceanografici con una precisione e una frequenza spazio-temporale senza precedenti. Questa ricerca innovativa ha permesso di mappare flussi d'acqua in aree remote e difficilmente accessibili con le tecnologie tradizionali, offrendo nuove informazioni sulle dinamiche dell'ecosistema oceanico meridionale e sul suo ruolo nel clima globale. Lo riferisce Le Monde.",
   "more": [
    "Gli elefanti marini sono mammiferi marini che compiono lunghe migrazioni e immersioni profonde in aree spesso inaccessibili alle navi da ricerca. Applicando sensori non invasivi sul loro corpo, gli scienziati possono monitorare temperatura e salinità dell'acqua su vasta scala, trasformando gli animali in preziosi alleati per lo studio dei cambiamenti climatici."
   ],
